class Solution {
public:
    int best = 0;
    void walk(TreeNode* node, int lo, int hi) {
        if (!node) return;
        best = max({best, abs(node->val - lo), abs(node->val - hi)});
        lo = min(lo, node->val);
        hi = max(hi, node->val);
        walk(node->left, lo, hi);
        walk(node->right, lo, hi);
    }
    int maxAncestorDiff(TreeNode* root) {
        walk(root, root->val, root->val);
        return best;
    }
};
